<div class="page-title"><div><p class="eyebrow">Official snapshot</p><h1><?= e($r['title']) ?> · Official results v<?= (int)$r['result_version'] ?></h1></div></div>
<p><?= badge($r['status']) ?> Finalised <?= e(fmt_dt($r['finalized_at'], 'd M Y, H:i:s')) ?> by <?= e($r['finalized_by_name']) ?> · <?= $r['published_at'] ? 'Published ' . e(fmt_dt($r['published_at'])) : 'Not published to participants' ?><?= $r['correction_reason'] ? ' · Correction: ' . e($r['correction_reason']) : '' ?></p>
<p><a href="<?= e(url('/admin/results?quiz=' . $r['quiz_id'])) ?>">‹ Back</a> · <a href="<?= e(url('/admin/results/view/' . $r['id'] . '/export')) ?>">Export CSV</a></p>
<section class="card"><h2>Rules saved with this snapshot</h2><ul class="plain"><?php foreach ($rules as $k => $v): ?><li><strong><?= e($k) ?></strong>: <?= e(is_scalar($v) ? (string)$v : json_encode($v)) ?></li><?php endforeach; ?></ul></section>
<div class="table-wrap"><table class="cards-sm"><thead><tr><th>Rank</th><th>Participant</th><th>Score</th><th>%</th><th>Time</th><th>Eligibility</th><th>Note</th></tr></thead><tbody>
<?php foreach ($entries as $e): ?><tr><td data-l="Rank"><?= $e['final_rank'] === null ? '—' : e(medal($e['badge'])) . ' ' . (int)$e['final_rank'] ?></td><td data-l="Participant"><?= e($e['participant_name']) ?></td><td data-l="Score"><?= e(num($e['score'])) ?>/<?= (int)$e['max_marks'] ?></td><td data-l="%"><?= e(num($e['percentage'])) ?>%</td><td data-l="Time"><?= e(fmt_duration($e['duration_seconds'] === null ? null : (int)$e['duration_seconds'])) ?></td><td data-l="Eligibility"><?= badge($e['eligibility']) ?></td><td data-l="Note"><?= e($e['note']) ?></td></tr><?php endforeach; ?></tbody></table></div>
